function zFor(c){return c===.9?1.645:c===.99?2.576:1.96}
function sampleSize(conf=.95,e=.05,N=null){const z=zFor(Number(conf)),n0=(z*z*.25)/(e*e);if(N&&N>0)return Math.ceil(n0/(1+(n0-1)/N));return Math.ceil(n0)}
