function ratio(rows,yes,valid=()=>true){const base=rows.filter(valid),hit=base.filter(yes);return{v:base.length?hit.length/base.length:null,n:base.length,h:hit.length}}
function mean(rows,key,valid=()=>true){const vals=rows.filter(valid).map(r=>Number(typeof key==="function"?key(r):r[key])).filter(Number.isFinite);return{v:vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null,n:vals.length}}
function median(vals){const a=vals.map(Number).filter(Number.isFinite).sort((x,y)=>x-y);if(!a.length)return null;const m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2}
