function syncBookingChannel(){const ov=$("overnight"),bc=$("bookingChannel");if(!ov||!bc)return;if(!bool(ov.value)){bc.value="not_applicable";bc.disabled=true}else{bc.disabled=false;if(bc.value==="not_applicable")bc.value="direct_whatsapp"}}
function topValid(rows,key){const c=topCounts(rows,key,1)[0];return c?{label:labelMap[c[0]]||c[0],n:c[1],base:rows.filter(r=>r[key]!==null&&r[key]!==undefined&&r[key]!=="").length}:null}
function autoFindings(rows,s){const out=[];const addTop=(key,title,prefix="")=>{const t=topValid(rows,key);if(t&&t.base)out.push([title,`${prefix}${t.label} · ${pct(t.n/t.base)} · base ${t.base}.`])};addTop("transport_mode","Cómo llega","Predomina ");addTop("primary_info_channel","Canal que más influye","Predomina ");addTop("primary_activity","Actividad principal","Predomina ");addTop("planning_lead","Cuándo decide","Predomina ");addTop("booking_channel","Cómo reserva","Predomina ");addTop("preferred_season","Época para volver","Predomina ");const rev=ratio(rows,r=>Number(r.revisit_score)>=8,r=>Number.isFinite(Number(r.revisit_score)));if(rev.n)out.push(["Intención de volver",`${pct(rev.v)} calificó con 8 a 10 su probabilidad de volver. Base ${rev.n}.`]);const party=topValid(rows,"party_type");if(party?.base)out.push(["Con quién viaja",`Predomina ${party.label} · ${pct(party.n/party.base)} · base ${party.base}.`]);return out}
