function questionHtml(q){const id=`custom-${q.id}`,req=q.required?"required":"";let input="";if(q.type==="single")input=`<select class="form-select custom-answer" data-q="${q.id}" ${req}><option value="">Seleccione</option>${arr(q.options).map(o=>`<option>${esc(o)}</option>`).join("")}</select>`;if(q.type==="multi")input=`<div>${arr(q.options).map(o=>`<label class="check-item mb-1"><input class="form-check-input custom-answer" type="checkbox" data-q="${q.id}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join("")}</div>`;if(q.type==="yesno")input=`<select class="form-select custom-answer" data-q="${q.id}" ${req}><option value="">Seleccione</option><option value="Sí">Sí</option><option value="No">No</option></select>`;if(q.type==="number")input=`<input type="number" class="form-control custom-answer" data-q="${q.id}" ${req}>`;if(q.type==="text")input=`<textarea class="form-control custom-answer" data-q="${q.id}" rows="2" ${req}></textarea>`;return`<div class="dynamic-question custom-q" id="${id}" data-condition='${esc(JSON.stringify(q.condition||null))}'><label>${esc(q.text)}${q.required?" *":""}</label>${input}</div>`}
