function parseCSV(text){let rows=[],row=[],cell="",quoted=false,delim=",";const first=text.split(/\r?\n/,1)[0]||"";if((first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length)delim=";";for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(!quoted&&c===delim){row.push(cell);cell="";continue}if(!quoted&&(c==="\n"||c==="\r")){if(c==="\r"&&n==="\n")i++;row.push(cell);cell="";if(row.some(x=>x!==""))rows.push(row);row=[];continue}cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
