function readCsv(e){const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{const rows=parseCSV(r.result);state.importHeaders=rows[0]||[];state.importRows=rows.slice(1).filter(x=>x.some(Boolean));renderMapping();renderPreview();$("runImportBtn").disabled=!state.importRows.length};r.readAsText(file)}
function renderMapping(){$("mappingGrid").innerHTML=state.importHeaders.map((h,i)=>`<div class="mapping-item"><label>${esc(h||`Columna ${i+1}`)}</label><select class="form-select form-select-sm map-select" data-col="${i}">${MAP_TARGETS.map(([v,l])=>`<option value="${v}">${l}</option>`).join("")}</select></div>`).join("")}
