async function runImport(){const s=activeStudy();if(!s){toast("Seleccioná un estudio.","warning");return}const map={};qsa(".map-select").forEach(x=>{if(x.value)map[x.dataset.col]=x.value});const imported=state.importRows.map(row=>{const x={id:uid(),client_id:uid(),organization_id:state.org.id,destination_id:state.destinationId,study_id:s.id,visited_at:new Date().toISOString(),field_point:"Histórico",origin_country:"Argentina",party_type:"No informado",party_size:1,trip_purpose:"No informado",survey_answers:{},created_by:state.user.id,source:"historical",created_at:new Date().toISOString()};Object.entries(map).forEach(([i,k])=>{let v=row[i];if(["nights","spend_food","spend_accommodation","recommend_score"].includes(k))v=num(String(v).replace(/\./g,"").replace(",","."));if(k==="overnight")v=/^(si|sí|true|1)$/i.test(v);if(k==="visited_at"){const d=new Date(v);v=Number.isNaN(d.getTime())?new Date().toISOString():d.toISOString()}x[k]=v||null});x.visitor_type=visitorType(x);return x});if(state.mode==="demo"){state.surveys.push(...imported);saveDemo()}else{for(let i=0;i<imported.length;i+=300){const{error}=await sb.from("visitor_records").insert(imported.slice(i,i+300));if(error){toast(error.message,"danger");return}}state.surveys.push(...imported)}renderAll();toast(`${imported.length} registros importados.`)}
function exportCsv(){const rows=studySurveys(),cols=["visited_at","field_point","time_band","visitor_type","origin_country","origin_province","residence_area","age_range","party_type","trip_purpose","overnight","nights","spend_currency",...SPEND_KEYS,"recommend_score","overall_satisfaction","has_unmet_need","unmet_category","would_pay","latitude","longitude","gps_accuracy_m","source"],csv=[cols.join(","),...rows.map(r=>cols.map(c=>`"${String(r[c]??"").replace(/"/g,'""')}"`).join(","))].join("\n");const b=new Blob(["\uFEFF"+csv],{type:"text/csv"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=`destintelligence-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function generateReport(){const s=state.studies.find(x=>x.id===$("reportStudySelect").value)||activeStudy(),rows=studySurveys(s.id),b=brand(),over=ratio(rows,r=>r.overnight,r=>r.overnight!==null),nn=mean(rows,"nights",r=>r.overnight),sp=mean(rows,dailySpend,r=>dailySpend(r)!==null),score=nps(rows),un=ratio(rows,r=>r.has_unmet_need,r=>r.has_unmet_need!==null),opp=opportunityRows(rows).slice(0,5),pur=topCounts(rows,"trip_purpose",8),findings=autoFindings(rows,s),m=INFERENTIAL.has(s.sampling_method)&&rows.length>=30?marginError(rows.length,s.confidence_level,s.population_size):null,verb=$("reportIncludeVerbatims").checked?rows.filter(r=>r.unmet_need_text).slice(0,5):[];const title=$("reportTitle").value,signature=$("reportSignature").value,w=window.open("","_blank");w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;color:#1d2923;margin:42px;line-height:1.45}header{border-top:10px solid ${b.primary_color};padding-top:25px}.logo{max-height:65px;max-width:180px}h1{font-size:32px;margin:18px 0 5px}h2{font-size:20px;margin-top:32px}.muted{color:#68766f}.grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:25px 0}.k{border:1px solid #dfe5e1;padding:12px;border-radius:9px}.k span{display:block;font-size:9px;color:#68766f}.k strong{font-size:19px}.note{background:#f3efe6;padding:13px;border-radius:9px;font-size:11px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left;font-size:11px}.quote{padding:10px;border-left:3px solid ${b.primary_color};background:#f8f8f5;margin:8px 0;font-size:11px}footer{margin-top:45px;border-top:1px solid #ddd;padding-top:14px;font-size:10px;color:#68766f}@media print{button{display:none}.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}</style></head><body><header>${b.logo_url?`<img class="logo" src="${b.logo_url}">`:""}<div class="muted">${esc(b.institution_name)}</div><h1>${esc(title)}</h1><p class="muted">${esc(s.name)} · ${s.start_date} a ${s.end_date}</p></header><div class="grid"><div class="k"><span>Muestra</span><strong>${rows.length}</strong></div><div class="k"><span>Pernoctan</span><strong>${pct(over.v)}</strong></div><div class="k"><span>Estadía</span><strong>${fmt(nn.v,1)}</strong></div><div class="k"><span>Gasto diario</span><strong>${fmt(sp.v,0)}</strong></div><div class="k"><span>NPS</span><strong>${score.v??"—"}</strong></div><div class="k"><span>Unmet need</span><strong>${pct(un.v)}</strong></div></div><h2>Ficha metodológica</h2><p>Método: ${esc(METHODS[s.sampling_method])}. Universo: ${esc(s.universe_definition)}. Muestra objetivo: ${s.target_sample_size}. ${m!==null?`Error máximo conservador de referencia global: ±${(m*100).toFixed(1)}%.`:"Se reporta como resultado descriptivo; no corresponde informar margen de error clásico."}</p><div class="note">Las bases válidas dependen de cada indicador. El tamaño de muestra no corrige sesgos de selección y la precisión de subgrupos debe evaluarse por separado.</div><h2>Composición de demanda</h2><table><tr><th>Motivo</th><th>Casos</th><th>% muestra</th></tr>${pur.map(([k,n])=>`<tr><td>${esc(k)}</td><td>${n}</td><td>${pct(n/Math.max(1,rows.length))}</td></tr>`).join("")}</table><h2>Oportunidades prioritarias</h2><table><tr><th>Oportunidad</th><th>n</th><th>Incidencia</th><th>Importancia</th><th>Intención de pago</th><th>Score</th></tr>${opp.map(o=>`<tr><td>${esc(o.category)}</td><td>${o.n}</td><td>${pct(o.incidence)}</td><td>${fmt(o.importance,1)}/10</td><td>${pct(o.pay)}</td><td><b>${o.score}</b></td></tr>`).join("")}</table>${verb.length?`<h2>Voz del visitante</h2>${verb.map(r=>`<div class="quote">“${esc(r.unmet_need_text)}” <span class="muted">— ${esc(r.unmet_category||"")}</span></div>`).join("")}`:""}${customReportSection(s,rows)}<footer>${esc(b.footer||"")} · ${esc(signature)} · Generado ${new Date().toLocaleDateString("es-AR")}</footer><button onclick="print()">Imprimir / Guardar PDF</button></body></html>`);w.document.close()}
function snapshotPayload(s){const rows=studySurveys(s.id),over=ratio(rows,r=>r.overnight,r=>r.overnight!==null),nn=mean(rows,"nights",r=>r.overnight),sp=mean(rows,dailySpend,r=>dailySpend(r)!==null),score=nps(rows),un=ratio(rows,r=>r.has_unmet_need,r=>r.has_unmet_need!==null),opp=opportunityRows(rows).slice(0,5);return{study_name:s.name,destination_name:activeDestination().name,sample_n:rows.length,overnight:over.v,avg_nights:nn.v,avg_daily_spend:sp.v,spend_currency:rows.find(r=>dailySpend(r)!==null)?.spend_currency||"USD",nps:score.v,unmet_rate:un.v,purposes:topCounts(rows,"trip_purpose",8),motivations:topCounts(rows,r=>arr(r.motivations),8),opportunities:opp.map(o=>({category:o.category,score:o.score,n:o.n})),method:METHODS[s.sampling_method],period:[s.start_date,s.end_date],branding:brand(),updated_at:new Date().toISOString()}}
