function visitorType(r){if(r.usual_commuter)return"commuter";if(!r.residence_area)return null;if(["junin_de_los_andes","caba"].includes(r.residence_area))return"resident";if(r.residence_area==="outside_argentina")return r.overnight?"tourist_international":"excursionist";if(["neuquen_outside_junin","gba"].includes(r.residence_area))return r.overnight?"tourist_domestic":"regional_visitor";return r.overnight?"tourist_domestic":"excursionist"}
function getSegment(r){if(!r.residence_area&&!r.trip_purpose&&!r.party_type)return"Sin segmentar";const spend=dailySpend(r)||0,m=arr(r.motivations),a=arr(r.activities);if(m.includes("Pesca deportiva")||a.includes("Pesca con mosca"))return"Pescadores especializados";if((r.children_count||0)>0||r.party_type==="Familia")return"Familias de naturaleza";if(m.includes("Turismo religioso / espiritual")||a.includes("Visita al Vía Christi")||a.includes("Visita al Santuario Laura Vicuña"))return"Viajeros espirituales";if(spend>=160||m.includes("Experiencias premium"))return"Alto valor";if(m.includes("Senderismo y montaña")||m.includes("Aventura")||a.includes("Ascenso / montaña"))return"Aventura y montaña";if(r.residence_area==="outside_argentina")return"Explorador internacional";return"Escapada patagónica"}
function qualityScore(s,rows){const ev=studyEvents(s.id),cov=studyCoverage(s.id),requiredDefs=CORE_QUESTIONS.filter(d=>{const c=coreQuestionState(d,s);return c.enabled&&c.required&&d.scope!=="block"}),completion=rows.length?rows.filter(r=>requiredDefs.every(d=>(d.fields||[]).every(f=>{const v=r[f];return Array.isArray(v)?v.length>0:v!==undefined&&v!==null&&v!==""}))).length/rows.length:0,gps=rows.length?rows.filter(r=>r.latitude!=null).length/rows.length:0,response=rows.length+ev.filter(x=>["refused","abandoned"].includes(x.outcome)).length?rows.length/(rows.length+ev.filter(x=>["refused","abandoned"].includes(x.outcome)).length):0,covAch=cov.length?cov.map(c=>Math.min(1,rows.filter(r=>r.field_point===c.field_point&&(c.time_band==="all_day"||r.time_band===c.time_band)).length/c.target_n)).reduce((a,b)=>a+b,0)/cov.length:0,advance=Math.min(1,rows.length/Math.max(1,s.target_sample_size));const score=Math.round(25*completion+20*gps+20*response+20*covAch+15*advance);return{score,label:score>=80?"Adecuada":score>=60?"En desarrollo":"Débil"}}
