function injectScreenGuides(){const guides={overview:["¿Para qué sirve esta pantalla?","Es el resumen para tomar decisiones. Mirá tendencias generales y, antes de comparar porcentajes, fijate siempre en la base que aparece debajo."],field:["Trabajo de campo, explicado simple","Sirve para comprobar que las encuestas se hicieron donde y cuando estaba previsto. Una muestra grande puede ser mala si todo se relevó en el mismo lugar o con el mismo tipo de persona."],studies:["Qué es un estudio","Es una campaña de investigación con fechas, público objetivo y una meta de encuestas. Si no sos especialista, definí claramente a quién querés estudiar y usá el método recomendado por tu responsable técnico."],forms:["Acá decidís qué se pregunta","La aplicación ya trae una base. Podés cambiarla. Abrí “Ver y editar cuestionario” y tocá Editar junto a la pregunta que quieras modificar."],demand:["Cómo leer los resultados","Cada porcentaje tiene una base válida: es la cantidad de personas que realmente respondieron esa pregunta. Si la base es chica, interpretá el dato con cautela."],opportunities:["Qué significa una oportunidad","Una necesidad frecuente y relevante puede señalar algo para investigar. El Opportunity Score ayuda a priorizar; no garantiza que un negocio vaya a ser rentable."],segments:["Qué es un segmento","Agrupa visitantes con comportamientos parecidos para entenderlos mejor. No significa que todas las personas del grupo sean iguales."],imports:["Para qué sirve importar histórico","Permite sumar encuestas anteriores. Si un dato no existía en el archivo viejo, queda vacío: la aplicación no lo inventa."],reports:["Qué genera el informe","Resume los principales resultados y la metodología para compartir con autoridades, equipos o prestadores."],public:["Qué se publica","Solo se publica información agregada. Las entrevistas individuales no se exponen en el tablero público."],users:["Roles y permisos","Dale a cada persona solo el acceso que necesita. El encuestador puede cargar datos; analistas y administradores gestionan estudios y resultados."],branding:["Marca institucional","Personaliza el nombre, color y logo que aparecerán en reportes y tableros públicos."]};for(const [view,[title,text]] of Object.entries(guides)){const sec=$(`view-${view}`);if(!sec||sec.querySelector(".screen-guide"))continue;const heading=sec.querySelector(".page-heading");if(!heading)continue;const box=document.createElement("details");box.className="screen-guide";box.innerHTML=`<summary><span class="guide-icon">?</span><strong>${esc(title)}</strong><span>Ver explicación</span></summary><p>${esc(text)}</p>`;heading.insertAdjacentElement("afterend",box)}}
function addHelpDots(){const helps={"Población estimada":"Cantidad aproximada de personas que forman el universo del estudio. Si no la conocés, podés dejarla vacía.","Confianza":"Nivel usado para calcular una referencia de precisión cuando el método permite inferencia estadística.","Margen objetivo":"Precisión deseada para una proporción global. No significa que todos los subgrupos tengan ese mismo error.","Muestra objetivo *":"Cantidad de entrevistas que se busca completar.","Base mínima por subgrupo":"Cantidad mínima de casos que querés tener antes de analizar un segmento por separado.","Regla sistemática":"Ejemplo: 3 significa entrevistar a cada tercera persona o grupo elegible según el protocolo."};qsa("label.form-label").forEach(l=>{const key=l.textContent.trim();const help=helps[key];if(!help||l.querySelector(".help-dot"))return;const b=document.createElement("button");b.type="button";b.className="help-dot";b.textContent="?";b.title=help;l.appendChild(b)})}
