function v43ChoiceRowHtml(o,i,fixed=false){return `<div class="choice-row ${fixed?"is-fixed":""}" data-value="${esc(o.value)}"><span class="choice-number">${i+1}</span><input type="text" class="form-control choice-label" value="${esc(o.label||"")}" placeholder="Escribí la respuesta"><div class="choice-actions"><button type="button" class="btn btn-light btn-sm choice-up" title="Subir">↑</button><button type="button" class="btn btn-light btn-sm choice-down" title="Bajar">↓</button><button type="button" class="btn btn-outline-danger btn-sm choice-remove" title="Retirar respuesta">Quitar</button></div></div>`}
function v43RefreshChoiceEditor(editor){if(!editor)return;const rows=[...editor.querySelectorAll('.choice-row')];rows.forEach((r,i)=>{const n=r.querySelector('.choice-number');if(n)n.textContent=i+1;const up=r.querySelector('.choice-up'),down=r.querySelector('.choice-down');if(up)up.disabled=i===0;if(down)down.disabled=i===rows.length-1});if(!rows.length&&!editor.querySelector('.choice-editor-empty'))editor.innerHTML='<div class="choice-editor-empty">Todavía no hay respuestas. Tocá “Agregar respuesta”.</div>'}
function v43BindChoiceEditor(editor){if(!editor||editor.dataset.bound==='1')return;editor.dataset.bound='1';editor.addEventListener('click',e=>{const row=e.target.closest('.choice-row');if(!row)return;if(e.target.closest('.choice-remove')){row.remove();v43RefreshChoiceEditor(editor);return}if(e.target.closest('.choice-up')){const prev=row.previousElementSibling;if(prev?.classList.contains('choice-row'))editor.insertBefore(row,prev);v43RefreshChoiceEditor(editor);return}if(e.target.closest('.choice-down')){const next=row.nextElementSibling;if(next?.classList.contains('choice-row'))editor.insertBefore(next,row);v43RefreshChoiceEditor(editor)}})}
function v43RenderChoiceEditor(editorId,options=[],fixed=false){const editor=$(editorId);if(!editor)return;const active=v43NormalizeOptions(options).filter(o=>o.active!==false);editor.dataset.fixed=fixed?'1':'0';editor.innerHTML=active.length?active.map((o,i)=>v43ChoiceRowHtml(o,i,fixed)).join(''):'<div class="choice-editor-empty">Todavía no hay respuestas. Tocá “Agregar respuesta”.</div>';v43BindChoiceEditor(editor);v43RefreshChoiceEditor(editor)}
